export function rentalQuote(startDate, endDate, pricePerDay, today) {
  if (!startDate || !endDate) {
    return { days: 0, total: 0, error: null }
  }

  const start = new Date(startDate)
  const end = new Date(endDate)
  const current = new Date(today)

  // Normalize to midnight to ensure pure date comparison regardless of timezones
  const normalize = (d) => new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()))

  const normStart = normalize(start)
  const normEnd = normalize(end)
  const normToday = normalize(current)

  if (normStart < normToday) {
    return { days: 0, total: 0, error: 'Start date cannot be in the past.' }
  }

  if (normEnd < normStart) {
    return { days: 0, total: 0, error: 'End date must be after start date.' }
  }

  // Calculate difference in milliseconds and convert to days
  // Using UTC ensures we don't hit DST issues during the subtraction
  const diffInMs = normEnd.getTime() - normStart.getTime()
  const msPerDay = 24 * 60 * 60 * 1000
  const days = Math.floor(diffInMs / msPerDay) + 1

  return {
    days: days,
    total: days * pricePerDay,
    error: null
  }
}

export default rentalQuote
